// 同步示例曲谱（在应用启动时调用）
// 覆盖模式：每次版本升级时，先清空示例文件夹内所有曲谱，再按定义重新写入
// 这样勘误修改会直接覆盖旧版本，不会产生历史版本堆积
function syncSampleData() {
  try {
    const currentVersion = wx.getStorageSync(SAMPLE_VERSION_KEY) || 0;
    
    // 如果已经是最新版本，直接返回
    if (currentVersion >= SAMPLE_DATA_VERSION) {
      console.log('[libraryManager] 示例曲谱已是最新版本:', currentVersion);
      return false;
    }
    
    console.log('[libraryManager] 同步示例曲谱（覆盖模式），从版本', currentVersion, '升级到', SAMPLE_DATA_VERSION);
    
    const data = getStorageData();
    const sampleDef = getSampleDataDefinition();
    const now = Date.now();
    
    // 确保示例文件夹存在
    let sampleFolder = data.folders.find(f => f.id === SAMPLE_FOLDER_ID);
    if (!sampleFolder) {
      sampleFolder = {
        ...sampleDef.folder,
        createTime: now,
        modifyTime: now
      };
      data.folders.push(sampleFolder);
      console.log('[libraryManager] 创建示例曲谱文件夹');
    } else {
      // 更新文件夹信息（保留创建时间）
      sampleFolder.name = sampleDef.folder.name;
      sampleFolder.isSystemSample = true;
      sampleFolder.modifyTime = now;
    }
    
    // 覆盖模式：移除示例文件夹内所有现有曲谱
    const samplePathStr = JSON.stringify([SAMPLE_FOLDER_ID]);
    const beforeCount = data.files.length;
    data.files = data.files.filter(f => JSON.stringify(f.path || []) !== samplePathStr);
    const removedCount = beforeCount - data.files.length;
    if (removedCount > 0) {
      console.log('[libraryManager] 移除示例文件夹内', removedCount, '个旧曲谱');
    }
    
    // 按定义重新添加所有示例曲谱
    sampleDef.files.forEach(sampleFile => {
      data.files.push({
        ...sampleFile,
        createTime: now,
        modifyTime: now,
        starred: sampleFile.starred || false
      });
    });
    console.log('[libraryManager] 写入', sampleDef.files.length, '个示例曲谱');
    
    saveStorageData(data);
    wx.setStorageSync(SAMPLE_VERSION_KEY, SAMPLE_DATA_VERSION);
    
    console.log('[libraryManager] 示例曲谱同步完成（覆盖），新版本:', SAMPLE_DATA_VERSION);
    return true;
  } catch (e) {
    console.error('[libraryManager] 同步示例曲谱失败:', e);
    return false;
  }
}

// 初始化示例数据（仅用于新用户首次使用）
// 保留此函数以兼容旧逻辑，但推荐使用 syncSampleData
function initSampleData() {
  const data = getStorageData();
  
  // 如果已有数据，调用同步函数而不是跳过
  if (data.folders.length > 0 || data.files.length > 0) {
    return syncSampleData();
  }
  
  // 新用户：直接使用同步函数初始化
  return syncSampleData();
}

